mapper.select:
SELECT p.id AS post_id, p.title AS post_title, p.content AS post_content, m.name AS membername, up.avatar AS avatar, -- ✅ 新增头像 p.create_time AS post_time, p.category_code AS category_code, pc.name AS category_name, GROUP_CONCAT(DISTINCT t.name) AS tag_title, GROUP_CONCAT(DISTINCT pi.image_url) AS image_urls, p.user_id AS userId FROM post p LEFT JOIN member m ON p.user_id = m.id LEFT JOIN user_profile up ON p.user_id = up.user_id -- ✅ 关联头像 LEFT JOIN post_category pc ON pc.code = p.category_code LEFT JOIN post_tag pt ON p.id = pt.post_id LEFT JOIN tag t ON pt.tag_id = t.id LEFT JOIN post_image pi ON p.id = pi.post_id WHERE p.status = '1'
AND p.category_code = #{categoryCode}
GROUP BY p.id, p.title, p.content, m.name, up.avatar, p.create_time, p.category_code, pc.name ORDER BY CASE WHEN #{view} = 'LATEST' THEN p.create_time END DESC, p.create_time DESC;
